//! The 3GPP sample entries and decoder-specific boxes on a real 3GP file.
//!
//! The file was generated by this workspace with `ffmpeg` (see
//! `fixtures/PROVENANCE.md`); the `MP4Box -diso` lines quoted beside the
//! assertions are the independent oracle.

use broadcast_core::{Parse, Serialize};
use isobmff::box_types::BoxIter;
use isobmff::init_segment::{SampleDescriptionBox, SampleEntryVariant};
use test_fixtures as fixtures;

fn stsd_of(data: &[u8]) -> Vec<u8> {
    fn walk(data: &[u8], found: &mut Vec<u8>) {
        for item in BoxIter::new(data) {
            let Ok(item) = item else { return };
            match &item.four_cc() {
                b"stsd" => *found = item.bytes.to_vec(),
                b"moov" | b"trak" | b"mdia" | b"minf" | b"stbl" => walk(item.body, found),
                _ => {}
            }
        }
    }
    let mut found = Vec::new();
    walk(data, &mut found);
    found
}

#[test]
fn h263_sample_entry_and_its_decoder_box_from_a_real_3gp_file() {
    // MP4Box -diso fixtures/mp4/3gpp/h263.3gp:
    //   <H263SampleDescriptionBox Size="127" Type="s263" Specification="3gpp"
    //    DataReferenceIndex="1" Width="176" Height="144" ... BitDepth="24">
    //   <H263ConfigurationBox Size="15" Type="d263" Specification="3gpp"
    //    Vendor="FFMP" Version="0" Profile="0" Level="10">
    let data = fixtures::read("mp4/3gpp/h263.3gp");
    let stsd = stsd_of(&data);
    let table = SampleDescriptionBox::parse(&stsd).expect("stsd parses");
    assert_eq!(table.try_to_bytes().expect("stsd serializes"), stsd);
    let Some(SampleEntryVariant::ThreeGppH263(entry)) = table.entries.first() else {
        panic!("expected the s263 entry kind");
    };
    assert_eq!(entry.visual().width, 176);
    assert_eq!(entry.visual().height, 144);
    let d263 = entry.decoder_specific().expect("d263 parses");
    assert_eq!(d263.vendor(), *b"FFMP");
    assert_eq!(d263.h263_level(), 10);
    assert_eq!(d263.h263_profile(), 0);
}
